            definitions[545] = ManifestRetained("Hero_Aurena", "h.aurena.ring.recall", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の生命", "Dream Ring Life"), MaxRank = 3, RankCost = 1, Mechanism = ManifestPair("Hero_Aurena", "h.aurena.ring.recall") }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C02", "C05" }, "B5の既存合わせ技と3段値を保持(旧Statの値0は実効果として数えない)。P(F,D): D OnHitで印→F OnHit。Echo 15/25/35, Arg0, CD0。羽根/欠片の個数は不変。 印はExpose2/3/4%・4秒・最大1つ・消費なし。出力は元の合わせ技が成立した時のみ(BridgeSuccess)。B(.)は出力に作用するが印のExpose値には掛けない。");
            definitions[546] = ManifestRetained("Hero_Aurena", "h.aurena.ring.rhythm", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の鼓動", "Dream Ring Rhythm"), MaxRank = 3, RankCost = 1, Mechanism = ManifestPair("Hero_Aurena", "h.aurena.ring.rhythm") }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C02", "C05" }, "B6の既存合わせ技と3段値を保持(旧Statの値0は実効果として数えない)。P(D,A): A OnHitで印→D OnHit、欠片1発1回。Echo 15/25/35, Arg0, CD0。両Identity成立。 印はExpose2/3/4%・4秒・最大1つ・消費なし。出力は元の合わせ技が成立した時のみ(BridgeSuccess)。B(.)は出力に作用するが印のExpose値には掛けない。");
            definitions[547] = ManifestRetained("Hero_Aurena", "h.aurena.ring.resolve", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の不屈", "Dream Ring Resolve"), MaxRank = 3, RankCost = 1, Mechanism = ManifestPair("Hero_Aurena", "h.aurena.ring.resolve") }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C02", "C05", "C06" }, "B7の既存合わせ技と3段値を保持(旧Statの値0は実効果として数えない)。P(A,C): C OnHitで印→A OnKill、敵1体1回。Shield 3/5/7, Arg0, CD0。自己回復を追加せず障壁で保護。 印はExpose2/3/4%・4秒・最大1つ・消費なし。出力は元の合わせ技が成立した時のみ(BridgeSuccess)。B(.)は出力に作用するが印のExpose値には掛けない。");
            definitions[548] = ManifestRetained("Hero_Aurena", "h.aurena.ring.renewal", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("夢輪の再生", "Dream Ring Renewal"), MaxRank = 5, RankCost = 1, Mechanism = ManifestNewPair("Hero_Aurena", "h.aurena.ring.renewal", "h.aurena.pair.8", "h.aurena.route.claw.6", "St_D_DisintegratingClaw", "h.aurena.route.golden-burst.6", "St_Q_GoldenBurst", BridgeGateKind.Mark, "St_Q_GoldenBurst", MemoryEventKind.Hit, "St_D_DisintegratingClaw", MemoryEventKind.Hit, BridgePayloadKind.AlliedWard, null, GimmickEffect.None, 0, new int[] { 400, 500, 600, 700, 800 }, true) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C02", "C05", "C12" }, "B8: P(C,G): G OnHitで印→C OnHit、基本攻撃1回につき1回(元のC/G接続を維持)。新しい代替橋 AlliedWard 4/5/6/7/8, Arg0, CD0、5段維持。旧HealthRegenを除去(HP再生は除去)。AU3 AlliedWard(C12)。B1/B8の印は互いに独立。");
            definitions[549] = ManifestRetained("Hero_Aurena", "h.aurena.route.golden-burst.2", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("黄金の被膜", "Golden Film"), MaxRank = 3, RankCost = 1, Mechanism = new AuthoredMechanismSpec { ChannelId = "h.aurena.route.golden-burst.2", Source = MemorySelector.Parse("St_Q_GoldenBurst"), Trigger = MemoryEventKind.ConfirmedUse, Budget = AttributionBudget.PerActivation, Kind = AuthoredMechanismKind.Gimmick, Gimmick = new GimmickDef { Trigger = GimmickTrigger.OnUse, Effect = GimmickEffect.Shield, Value = 2m, Arg = 0, Cooldown = 0f } } }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C06" }, "値・発動は維持しCDだけ変更: G OnUse Shield(1段ごと2), Arg0, CD 4秒→0。通常Shieldの有限1枚管理(AU4/C06)で無限加算の理由がなくなるため。");
            definitions[550] = ManifestRetained("Hero_Aurena", "h.aurena.route.reduction.4", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("金片の薄衣", "Shard Veil"), MaxRank = 3, RankCost = 1, Mechanism = new AuthoredMechanismSpec { ChannelId = "h.aurena.route.reduction.4", Source = MemorySelector.Parse("St_Q_Reduction"), Trigger = MemoryEventKind.Hit, Budget = AttributionBudget.PerActivation, Kind = AuthoredMechanismKind.Gimmick, Gimmick = new GimmickDef { Trigger = GimmickTrigger.OnHit, Effect = GimmickEffect.Shield, Value = 1m, Arg = 0, Cooldown = 0f } } }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C06" }, "値・発動は維持しCDだけ変更: D OnHit Shield(1段ごと1), Arg0, CD 3秒→0。通常Shieldの有限1枚管理(AU4/C06)のため。");
            definitions[551] = ManifestRetained("Hero_Aurena", "h.aurena.route.chain-reaction.2", new ClusterStarDef { Kind = ClusterStarKind.Notable, Name = new Txt("分解の光", "Dismantle Light"), MaxRank = 3, RankCost = 1, Mechanism = new AuthoredMechanismSpec { ChannelId = "h.aurena.route.chain-reaction.2", Source = MemorySelector.Parse("St_R_ChainReaction"), Trigger = MemoryEventKind.Hit, Budget = AttributionBudget.PerActivation, Kind = AuthoredMechanismKind.Gimmick, Gimmick = new GimmickDef { Trigger = GimmickTrigger.OnHit, Effect = GimmickEffect.Element, Value = 30m, Arg = 2, Cooldown = 0f } } }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C02" }, "値・発動は維持しCDだけ変更: A OnHit Element 30/60/90, Arg2(光), CD 1秒→0。光上限5を守る。");
            definitions[552] = ManifestRetained("Hero_Aurena", "h.aurena.key", new ClusterStarDef { Kind = ClusterStarKind.Keystone, Name = new Txt("血の献身", "Blood Devotion"), MaxRank = 1, RankCost = 1, KeystoneDefinition = AuthoredKeystoneCompiler.Compile("h.aurena.key", Array.Empty<string>(), new AuthoredKeystoneSpec[] { new AuthoredKeystoneSpec { Layer = KeystoneLayer.ModEffect, Scope = new KeystoneScope(targetEffectSet: new GimmickEffect[] { GimmickEffect.Shield, GimmickEffect.Burst, GimmickEffect.Daze, GimmickEffect.Echo, GimmickEffect.Element, GimmickEffect.ElementEdge, GimmickEffect.Expose, GimmickEffect.Rampart, GimmickEffect.Ricochet, GimmickEffect.Sap, GimmickEffect.Wound }, sourceSelectors: new[] { MemorySelector.Parse("@Q") }), Field = KeystoneField.Value, Percent = 100m } }, new AuthoredKeystoneSpec[] { new AuthoredKeystoneSpec { Layer = KeystoneLayer.StarMemoryDamage, Scope = new KeystoneScope(sourceSelectors: new[] { MemorySelector.Parse("@Q") }), Disable = true } }, prerequisites: Array.Empty<string>(), cost: Content.KeystoneCost) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C03", "C07", "C15" }, "既存刻印K1の同ID再設計(核位置不変、1段)。旧Overloadの汎用AD/AP上昇を除去し、補正源別倍率(AU5)へ置換。");
            definitions[553] = ManifestRetained("Hero_Aurena", "h.aurena.key2", new ClusterStarDef { Kind = ClusterStarKind.Keystone, Name = new Txt("満ちた聖杯", "Brimming Chalice"), MaxRank = 1, RankCost = 1, KeystoneDefinition = AuthoredKeystoneCompiler.Compile("h.aurena.key2", Array.Empty<string>(), new AuthoredKeystoneSpec[] { new AuthoredKeystoneSpec { Layer = KeystoneLayer.ModEffect, Scope = new KeystoneScope(), Grant = new AuthoredMechanismSpec { ChannelId = "h.aurena.key2.grant", Kind = AuthoredMechanismKind.SacrificeShield } } }, new AuthoredKeystoneSpec[] { new AuthoredKeystoneSpec { Layer = KeystoneLayer.ModEffect, Scope = new KeystoneScope(targetEffectSet: new GimmickEffect[] { GimmickEffect.Echo, GimmickEffect.Burst, GimmickEffect.ElementEdge, GimmickEffect.Ricochet }, sourceSelectors: new[] { MemorySelector.Parse("St_Q_GoldenBurst"), MemorySelector.Parse("St_Q_Reduction") }), Field = KeystoneField.Value, Percent = -40m } }, prerequisites: Array.Empty<string>(), cost: Content.KeystoneCost) }, Array.Empty<string>(), Array.Empty<string>(), Array.Empty<AuthoredStarEdge>(), null, "docs/specs/v1.31-clusters-aurena.md", new string[] { "C01", "C03", "C06", "C07", "C11", "C15" }, "既存IDの再設計K2(AU6/C11、核位置不変、1段)。旧OverflowingLifeの高HP/超過回復前提を除去。犠牲0なら発生0で、別の効果には置き換えない。");
